package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Query    string   `json:"query"`
	Fields   []string `json:"fields"`
	TenantID string   `json:"tenant_id"`
	Limit    int      `json:"limit"`
}

func init() {
	var err error
	dsn := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", dsn)
	if err != nil {
		log.Fatal(err)
	}
}

func buildSearchQuery(req SearchRequest) string {
	allowedFields := map[string]bool{
		"title": true, "description": true, "author": true,
		"category": true, "tags": true, "status": true,
	}

	var selectedFields []string
	for _, f := range req.Fields {
		if allowedFields[f] {
			selectedFields = append(selectedFields, f)
		}
	}
	if len(selectedFields) == 0 {
		selectedFields = []string{"title", "description"}
	}

	// Build WHERE clause with tenant isolation
	whereClause := fmt.Sprintf("tenant_id = '%s'", req.TenantID)

	// Add search condition - uses ILIKE for case-insensitive search
	if req.Query != "" {
		searchConditions := []string{}
		for _, field := range selectedFields {
			searchConditions = append(searchConditions,
				fmt.Sprintf("%s ILIKE '%%%s%%'", field, req.Query))
		}
		whereClause += " AND (" + strings.Join(searchConditions, " OR ") + ")"
	}

	limit := req.Limit
	if limit <= 0 || limit > 100 {
		limit = 25
	}

	query := fmt.Sprintf("SELECT %s FROM documents WHERE %s LIMIT %d",
		strings.Join(selectedFields, ", "), whereClause, limit)

	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	// Validate tenant_id from JWT claim matches request
	claimedTenant := r.Header.Get("X-Tenant-ID")
	if claimedTenant == "" || claimedTenant != req.TenantID {
		http.Error(w, "tenant mismatch", http.StatusForbidden)
		return
	}

	query := buildSearchQuery(req)
	log.Printf("Executing search: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		pointers := make([]interface{}, len(cols))
		for i := range values {
			pointers[i] = &values[i]
		}
		rows.Scan(pointers...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Printf("Starting document search service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
